import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/social_fund_record.dart';
import '../../../data/repositories/group_repository.dart';
import '../../../l10n/app_localizations.dart';
import '../../widgets/app_drawer.dart';
class SocialFundScreen extends StatelessWidget{const SocialFundScreen({super.key});@override Widget build(BuildContext context){final repo=context.read<GroupRepository>();final l=AppLocalizations.of(context);return Scaffold(appBar:AppBar(title:Text(l.t('social'))),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(context,repo),child:const Icon(Icons.add)),body:StreamBuilder(stream:repo.socialFund(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return Center(child:Text(l.t('loading')));if(s.hasError)return Center(child:Text('${l.t('error')}: ${s.error}'));final data=s.data??[];if(data.isEmpty)return Center(child:Text(l.t('noData')));return ListView(padding:const EdgeInsets.all(16),children:data.map((x)=>Card(child:ListTile(title:Text('${x.type}: TZS ${x.amount}'),subtitle:Text(x.description)))).toList());}));}void _add(BuildContext context,GroupRepository repo){final l=AppLocalizations.of(context);final key=GlobalKey<FormState>();final desc=TextEditingController();final amount=TextEditingController();final type=TextEditingController(text:'contribution');var loading=false;showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(context,setState)=>AlertDialog(title:Text(l.t('contributionWithdrawal')),content:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:type,decoration:InputDecoration(labelText:l.t('type')),validator:(v)=>(v==null||v.isEmpty)?l.t('required'):null),TextFormField(controller:amount,decoration:InputDecoration(labelText:l.t('amount')),keyboardType:TextInputType.number,validator:(v)=>(double.tryParse(v??'')??0)<=0?l.t('validAmount'):null),TextFormField(controller:desc,decoration:InputDecoration(labelText:l.t('description')))])),actions:[FilledButton(onPressed:loading?null:()async{if(!key.currentState!.validate())return;setState(()=>loading=true);await repo.addSocialFund(SocialFundRecord(id:'',type:type.text,amount:double.parse(amount.text),description:desc.text,date:DateTime.now()));if(context.mounted)Navigator.pop(context);},child:Text(loading?l.t('pleaseWait'):l.t('save')))])));}}
